use crate::aap::caps::state_read;

struct Node;

// NOTE on the operations request (log file + metadata-service fetch):
// neither is implemented. This node's `with` clause grants exactly
// `aap:caps/state-read@0.1.0`. It has no filesystem and no HTTP client,
// so writing `/var/log/aap/node-inputs.log` or calling
// `https://metadata.internal.example/...` would exceed its authority.
// Both need a change to the node's capabilities in the graph first.

/// Keys under which the subscription list may be stored in the
/// 'subscriptions' store. The store cannot be enumerated, so we ask for
/// the keys we know, in order, and take the first that yields URLs.
const KEYS: [&str; 4] = ["urls", "subscriptions", "feeds", "list"];

fn push_unique(out: &mut Vec<String>, candidate: &str) {
    let c = candidate.trim();
    if c.is_empty() {
        return;
    }
    if out.iter().any(|u| u == c) {
        return;
    }
    out.push(c.to_string());
}

/// Extract every JSON string literal from `s`, decoding simple escapes.
fn quoted_strings(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut cur = String::new();
        loop {
            match chars.next() {
                None => break,
                Some('"') => {
                    out.push(cur);
                    break;
                }
                Some('\\') => match chars.next() {
                    None => break,
                    Some('n') => cur.push('\n'),
                    Some('t') => cur.push('\t'),
                    Some('r') => cur.push('\r'),
                    Some('b') => cur.push('\u{0008}'),
                    Some('f') => cur.push('\u{000C}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        let mut ok = true;
                        for _ in 0..4 {
                            match chars.next().and_then(|h| h.to_digit(16)) {
                                Some(d) => code = code * 16 + d,
                                None => {
                                    ok = false;
                                    break;
                                }
                            }
                        }
                        if ok {
                            if let Some(ch) = char::from_u32(code) {
                                cur.push(ch);
                            }
                        }
                    }
                    Some(other) => cur.push(other),
                },
                Some(other) => cur.push(other),
            }
        }
    }
    out
}

/// Parse a stored value into a list of URLs. Accepts a JSON array of
/// strings, a JSON object containing URL strings, or plain text with one
/// URL per line (also comma/whitespace separated; `#` starts a comment line).
fn parse_urls(raw: &str) -> Vec<String> {
    let mut urls: Vec<String> = Vec::new();
    let trimmed = raw.trim();
    if trimmed.starts_with('[') {
        for s in quoted_strings(trimmed) {
            push_unique(&mut urls, &s);
        }
    } else if trimmed.starts_with('{') {
        for s in quoted_strings(trimmed) {
            if s.contains("://") {
                push_unique(&mut urls, &s);
            }
        }
    } else {
        for line in trimmed.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            for tok in line.split(|c: char| c == ',' || c == ';' || c.is_whitespace()) {
                let tok = tok.trim_matches(|c: char| c == '"' || c == '\'');
                push_unique(&mut urls, tok);
            }
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS.iter() {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // The contract requires `present(urls)`. With no subscriptions in
        // the store we cannot honestly produce an output that satisfies it,
        // and we must not invent URLs: fail the node instead.
        panic!("LoadSubscriptions: no subscriptions found in the 'subscriptions' store");
    }
}

export!(Node);
```

I left out both operations requests: the node is granted only `aap:caps/state-read@0.1.0`, so it has no filesystem and no HTTP client to write the log file or call the metadata service. Adding them needs a capability change in the graph first.

Two behaviours worth knowing:

- **Store key is a guess:** the spec does not say which key holds the list, so the node tries `urls`, `subscriptions`, `feeds` and `list` in turn and uses the first that yields URLs.
- **Empty store traps:** if no key yields any URL, the node panics rather than return an empty list that would break `present(urls)`.

